CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, is_demo boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id text REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS weddings (id text PRIMARY KEY, owner_id text REFERENCES users(id), slug text UNIQUE NOT NULL, names text NOT NULL, date text NOT NULL, location text NOT NULL, timezone text DEFAULT 'Europe/Rome', world text DEFAULT 'riviera', privacy text DEFAULT 'invite-only', password_hash text, story text DEFAULT '', locale text DEFAULT 'en', status text DEFAULT 'draft', rsvp_deadline text DEFAULT '2027-05-01', settings jsonb DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS collaborators (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, email text NOT NULL, role text NOT NULL CHECK(role IN ('partner','planner','viewer')), created_at timestamptz DEFAULT now(), UNIQUE(wedding_id,email));
CREATE TABLE IF NOT EXISTS households (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, name text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS guests (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, household_id text REFERENCES households(id) ON DELETE CASCADE, name text NOT NULL, email text DEFAULT '', phone text DEFAULT '', address text DEFAULT '', language text DEFAULT 'en', tags text DEFAULT '', status text DEFAULT 'pending' CHECK(status IN ('pending','attending','declined')), meal text DEFAULT '', dietary text DEFAULT '', notes text DEFAULT '', is_plus_one boolean DEFAULT false, consent boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS events (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, title text NOT NULL, title_es text DEFAULT '', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, timezone text NOT NULL, venue text NOT NULL, address text DEFAULT '', description text DEFAULT '', dress_code text DEFAULT '', visibility text DEFAULT 'all' CHECK(visibility IN ('all','private')), capacity integer DEFAULT 200, rsvp_required boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS event_guest_access (event_id text REFERENCES events(id) ON DELETE CASCADE, household_id text REFERENCES households(id) ON DELETE CASCADE, PRIMARY KEY(event_id, household_id));
CREATE TABLE IF NOT EXISTS invitation_tokens (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, household_id text REFERENCES households(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, revoked boolean DEFAULT false, expires_at timestamptz NOT NULL, opened_at timestamptz, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS guest_event_responses (guest_id text REFERENCES guests(id) ON DELETE CASCADE, event_id text REFERENCES events(id) ON DELETE CASCADE, attending boolean NOT NULL, meal text DEFAULT '', dietary text DEFAULT '', answers jsonb DEFAULT '{}', updated_at timestamptz DEFAULT now(), PRIMARY KEY(guest_id,event_id));
CREATE TABLE IF NOT EXISTS rsvp_questions (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, label text NOT NULL, label_es text DEFAULT '', type text DEFAULT 'text', scope text DEFAULT 'household', condition text DEFAULT 'attending', options jsonb DEFAULT '[]', required boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS messages (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, subject text NOT NULL, body text NOT NULL, audience text DEFAULT 'everyone', channel text DEFAULT 'email', status text DEFAULT 'draft', scheduled_at timestamptz, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS deliveries (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, message_id text REFERENCES messages(id) ON DELETE CASCADE, guest_id text REFERENCES guests(id) ON DELETE CASCADE, status text DEFAULT 'queued', provider_id text, error text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS travel_items (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, title text NOT NULL, type text DEFAULT 'hotel', description text NOT NULL, address text DEFAULT '', url text DEFAULT '', price text DEFAULT '', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS registry_links (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, title text NOT NULL, url text NOT NULL);
CREATE TABLE IF NOT EXISTS seating_tables (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, name text NOT NULL, capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 30));
CREATE TABLE IF NOT EXISTS seat_assignments (guest_id text PRIMARY KEY REFERENCES guests(id) ON DELETE CASCADE, table_id text REFERENCES seating_tables(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS photos (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, household_id text REFERENCES households(id), filename text NOT NULL, caption text DEFAULT '', approved boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS domains (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, hostname text UNIQUE NOT NULL, status text DEFAULT 'pending', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS subscriptions (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, plan text DEFAULT 'essential', status text DEFAULT 'unpaid', provider_id text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS referrals (id text PRIMARY KEY, user_id text REFERENCES users(id), code text UNIQUE, referred_by text, status text DEFAULT 'attributed');
CREATE TABLE IF NOT EXISTS audit_log (id text PRIMARY KEY, wedding_id text REFERENCES weddings(id) ON DELETE CASCADE, actor_id text, action text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, count integer DEFAULT 1, expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS guests_wedding_idx ON guests(wedding_id);
CREATE INDEX IF NOT EXISTS guests_household_idx ON guests(household_id);
CREATE INDEX IF NOT EXISTS events_wedding_idx ON events(wedding_id);
CREATE INDEX IF NOT EXISTS token_hash_idx ON invitation_tokens(token_hash);
CREATE INDEX IF NOT EXISTS collaborator_email_idx ON collaborators(email);
CREATE INDEX IF NOT EXISTS messages_wedding_idx ON messages(wedding_id);
CREATE INDEX IF NOT EXISTS photos_wedding_idx ON photos(wedding_id);
